window.CRITIQUE_ADDITIONS = {"retrieved":"2026-11-15","works":[{"artist":"Mierle Laderman Ukeles","project":"Hartford Wash: Washing, Tracks, Maintenance (Outside)","year":"1973","from":1973,"note":"One of her Maintenance Art performances at the Wadsworth Atheneum, 1973 to 1974","story":"In 1969, after the birth of her first child, Ukeles wrote her Manifesto for Maintenance Art, which argued that the daily work of cleaning, keeping and caring, done unseen and mostly by women, was as much art as anything shown in a gallery. In 1973 the Wadsworth Atheneum in Hartford let her put it into practice: she washed the plaza and steps outside the museum on her hands and knees, then the floors inside, during opening hours. The pictures show the work a museum depends on and does not exhibit.","images":[{"n":"ukeles-washing-tracks-maintenance-outside-1","src":"assets/critique_additions/ukeles-washing-tracks-maintenance-outside-1.jpg","thumb":"assets/critique_additions/ukeles-washing-tracks-maintenance-outside-1_t.jpg","mid":"assets/critique_additions/ukeles-washing-tracks-maintenance-outside-1_m.jpg","w":1500,"h":1021,"artist":"Mierle Laderman Ukeles","project":"Hartford Wash: Washing, Tracks, Maintenance (Outside)","year":"1973","kind":"Performance at the Wadsworth Atheneum, Hartford, 1973","credit":"","licence":"","source":"https://feldmangallery.com/artist-home/mierle-laderman-ukeles"},{"n":"ukeles-washing-tracks-maintenance-outside-2","src":"assets/critique_additions/ukeles-washing-tracks-maintenance-outside-2.jpg","thumb":"assets/critique_additions/ukeles-washing-tracks-maintenance-outside-2_t.jpg","mid":"assets/critique_additions/ukeles-washing-tracks-maintenance-outside-2_m.jpg","w":1008,"h":1500,"artist":"Mierle Laderman Ukeles","project":"Hartford Wash: Washing, Tracks, Maintenance (Outside)","year":"1973","kind":"Performance at the Wadsworth Atheneum, Hartford, 1973","credit":"","licence":"","source":"https://feldmangallery.com/artist-home/mierle-laderman-ukeles"}]},{"artist":"Andrea Fraser","project":"Museum Highlights: A Gallery Talk","year":"1989","from":1989,"note":"","story":"As Jane Castleton, an invented volunteer docent, Fraser led visitors through the Philadelphia Museum of Art in 1989. She praised the water fountain, the cafeteria and the toilets in the same gushing words a guide uses for the paintings, with lines taken from the museum's own guidebooks, annual reports and older writing on museums. The talk asks what a museum teaches its visitors besides art: manners, taste and the idea that culture improves those it lets in. Tate holds the video of the performance.","images":[{"n":"fraser-museum-highlights-1","src":"assets/critique_additions/fraser-museum-highlights-1.jpg","thumb":"assets/critique_additions/fraser-museum-highlights-1_t.jpg","mid":"assets/critique_additions/fraser-museum-highlights-1_m.jpg","w":1536,"h":1090,"artist":"Andrea Fraser","project":"Museum Highlights: A Gallery Talk","year":"1989","kind":"Performance at the Philadelphia Museum of Art, 1989","credit":"","licence":"","source":"https://www.tate.org.uk/art/artworks/fraser-museum-highlights-a-gallery-talk-t13715"}]},{"artist":"Guerrilla Girls","project":"You’re Seeing Less Than Half the Picture","year":"1989","from":1989.5,"note":"","story":"The Guerrilla Girls formed in New York in 1985, after the Museum of Modern Art opened a survey of recent painting and sculpture with barely a dozen women among more than 160 artists. They work anonymously in gorilla masks, taking the names of dead women artists, and answer with counts: how many women and artists of colour museums and galleries show. This 1989 poster says it in one line, that a collection without them leaves out more than half the picture. Tate holds a set of their posters from these years.","images":[{"n":"guerrilla-girls-less-than-half-the-picture-1","src":"assets/critique_additions/guerrilla-girls-less-than-half-the-picture-1.jpg","thumb":"assets/critique_additions/guerrilla-girls-less-than-half-the-picture-1_t.jpg","mid":"assets/critique_additions/guerrilla-girls-less-than-half-the-picture-1_m.jpg","w":2400,"h":1851,"artist":"Guerrilla Girls","project":"You’re Seeing Less Than Half the Picture","year":"1989","kind":"Poster, 1989. Tate collection","credit":"","licence":"","source":"https://www.tate.org.uk/art/artworks/guerrilla-girls-youre-seeing-less-than-half-the-picture-p78790"}]},{"artist":"Guerrilla Girls","project":"Guerrilla Girls’ Code of Ethics for Art Museums","year":"1990","from":1990,"note":"","story":"By 1990 the Guerrilla Girls had spent five years posting statistics about who museums show. This poster turns to how museums behave, set out as a list of commandments addressed to the institutions themselves. Like their other posters it was pasted up in the streets of New York and later collected by the museums it addressed, Tate among them.","images":[{"n":"guerrilla-girls-code-of-ethics-for-art-museums-1","src":"assets/critique_additions/guerrilla-girls-code-of-ethics-for-art-museums-1.jpg","thumb":"assets/critique_additions/guerrilla-girls-code-of-ethics-for-art-museums-1_t.jpg","mid":"assets/critique_additions/guerrilla-girls-code-of-ethics-for-art-museums-1_m.jpg","w":2400,"h":1864,"artist":"Guerrilla Girls","project":"Guerrilla Girls’ Code of Ethics for Art Museums","year":"1990","kind":"Poster, 1990. Tate collection","credit":"","licence":"","source":"https://www.tate.org.uk/art/artworks/guerrilla-girls-guerrilla-girls-code-of-ethics-for-art-museums-p78795"}]},{"artist":"Hito Steyerl","project":"Guards","year":"2012","from":2012.1,"note":"A film made at the Art Institute of Chicago with museum guards who had served in the military or the police","story":"Steyerl made Guards in 2012 at the Art Institute of Chicago, filming two of the museum's guards, both of whom had served in the military or the police. In the galleries they describe how they would secure a room, where a threat would come from and how to clear it, as if the museum were a combat zone. The film sets the protection of art beside the training of people whose earlier jobs were violence, and asks what the calm of a museum rests on.","images":[{"n":"steyerl-guards-1","src":"assets/critique_additions/steyerl-guards-1.jpg","thumb":"assets/critique_additions/steyerl-guards-1_t.jpg","mid":"assets/critique_additions/steyerl-guards-1_m.jpg","w":2400,"h":1600,"artist":"Hito Steyerl","project":"Guards","year":"2012","kind":"Installation view, Artists Space, New York, 2015","credit":"Courtesy the artist and Andrew Kreps, New York.","licence":"","source":"https://artistsspace.org/exhibitions/hito-steyerl"},{"n":"steyerl-guards-2","src":"assets/critique_additions/steyerl-guards-2.jpg","thumb":"assets/critique_additions/steyerl-guards-2_t.jpg","mid":"assets/critique_additions/steyerl-guards-2_m.jpg","w":1350,"h":2400,"artist":"Hito Steyerl","project":"Guards","year":"2012","kind":"Image from the video. KOW, Berlin","credit":"","licence":"","source":"https://kow-berlin.com/artists/hito-steyerl/guards-2012"}]},{"artist":"Hito Steyerl","project":"Is the Museum a Battlefield?","year":"2013","from":2013,"note":"","story":"Steyerl first gave this as a lecture at the 13th Istanbul Biennial in 2013. It follows a bullet casing found in Kurdistan, near where her friend Andrea Wolf was killed in 1998, back to the arms makers that produced such ammunition, and finds some of the same companies among the sponsors of art events and museums. The talk was turned into a two-channel video installation, which the Museo Reina Sofía in Madrid now holds.","images":[{"n":"steyerl-is-the-museum-a-battlefield-1","src":"assets/critique_additions/steyerl-is-the-museum-a-battlefield-1.jpg","thumb":"assets/critique_additions/steyerl-is-the-museum-a-battlefield-1_t.jpg","mid":"assets/critique_additions/steyerl-is-the-museum-a-battlefield-1_m.jpg","w":2303,"h":1535,"artist":"Hito Steyerl","project":"Is the Museum a Battlefield?","year":"2013","kind":"Two-channel video installation. Collection of the Museo Reina Sofía, Madrid","credit":"","licence":"","source":"https://www.museoreinasofia.es/en/collections/artwork/museum-battlefield"},{"n":"steyerl-is-the-museum-a-battlefield-2","src":"assets/critique_additions/steyerl-is-the-museum-a-battlefield-2.jpg","thumb":"assets/critique_additions/steyerl-is-the-museum-a-battlefield-2_t.jpg","mid":"assets/critique_additions/steyerl-is-the-museum-a-battlefield-2_m.jpg","w":2288,"h":1535,"artist":"Hito Steyerl","project":"Is the Museum a Battlefield?","year":"2013","kind":"Two-channel video installation. Collection of the Museo Reina Sofía, Madrid","credit":"","licence":"","source":"https://www.museoreinasofia.es/en/collections/artwork/museum-battlefield"}]},{"artist":"Hito Steyerl","project":"Duty Free Art","year":"2015","from":2015.1,"note":"A lecture given at Artists Space, New York, in March 2015, on freeports, where artworks worth millions are stored untaxed","story":"Steyerl gave Duty Free Art as a lecture at Artists Space in New York in March 2015, during her exhibition there. It is about freeports, the bonded warehouses in places such as Geneva where art worth millions is stored untaxed and rarely seen, bought and sold without leaving the building. For Steyerl the freeport is the art world's offshore account, a museum with no public. The lecture was later shown as a video installation.","images":[{"n":"steyerl-duty-free-art-1","src":"assets/critique_additions/steyerl-duty-free-art-1.jpg","thumb":"assets/critique_additions/steyerl-duty-free-art-1_t.jpg","mid":"assets/critique_additions/steyerl-duty-free-art-1_m.jpg","w":2400,"h":1628,"artist":"Hito Steyerl","project":"Duty Free Art","year":"2015","kind":"Installation view, Artists Space, New York, 2015","credit":"Courtesy of the artist.","licence":"","source":"https://artistsspace.org/exhibitions/hito-steyerl"},{"n":"steyerl-duty-free-art-2","src":"assets/critique_additions/steyerl-duty-free-art-2.jpg","thumb":"assets/critique_additions/steyerl-duty-free-art-2_t.jpg","mid":"assets/critique_additions/steyerl-duty-free-art-2_m.jpg","w":2400,"h":1623,"artist":"Hito Steyerl","project":"Duty Free Art","year":"2015","kind":"Installation view. KOW, Berlin","credit":"","licence":"","source":"https://kow-berlin.com/artists/hito-steyerl/duty-free-art"}]},{"artist":"Maria Eichhorn","project":"5 weeks, 25 days, 175 hours","year":"2016","from":2016.1,"note":"For the length of the exhibition, 23 April to 29 May 2016, the gallery and office were closed and the staff were not working","story":"Chisenhale Gallery in London commissioned Eichhorn for 2016. She answered by closing it: for the five weeks of the exhibition, the gallery and its office stayed shut and the staff did not work, while being paid as usual. The title counts the working time they were given back. A symposium on work and its refusal opened the project, and the closed gate with its notice was all a visitor saw. The piece asked what a small public gallery runs on, and who pays for its constant activity.","images":[{"n":"eichhorn-5-weeks-25-days-175-hours-1","src":"assets/critique_additions/eichhorn-5-weeks-25-days-175-hours-1.jpg","thumb":"assets/critique_additions/eichhorn-5-weeks-25-days-175-hours-1_t.jpg","mid":"assets/critique_additions/eichhorn-5-weeks-25-days-175-hours-1_m.jpg","w":2400,"h":1802,"artist":"Maria Eichhorn","project":"5 weeks, 25 days, 175 hours","year":"2016","kind":"The closed gallery, Chisenhale Gallery, London, 2016","credit":"Images courtesy of the artist. Commissioned by Chisenhale Gallery. Photos by Andy Keate.","licence":"","source":"https://www.contemporaryartlibrary.org/project/maria-eichhorn-at-chisenhale-gallery-london-9697"},{"n":"eichhorn-5-weeks-25-days-175-hours-2","src":"assets/critique_additions/eichhorn-5-weeks-25-days-175-hours-2.jpg","thumb":"assets/critique_additions/eichhorn-5-weeks-25-days-175-hours-2_t.jpg","mid":"assets/critique_additions/eichhorn-5-weeks-25-days-175-hours-2_m.jpg","w":1502,"h":2000,"artist":"Maria Eichhorn","project":"5 weeks, 25 days, 175 hours","year":"2016","kind":"Sign on the gate, Chisenhale Gallery, London, 2016","credit":"Images courtesy of the artist. Commissioned by Chisenhale Gallery. Photos by Andy Keate.","licence":"","source":"https://www.contemporaryartlibrary.org/project/maria-eichhorn-at-chisenhale-gallery-london-9697"}]},{"artist":"Occupy Museums","project":"Debtfair","year":"2017","from":2017,"note":"","story":"Occupy Museums grew out of Occupy Wall Street in 2011, taking its protest against debt and inequality into New York's museums. For the 2017 Whitney Biennial it showed Debtfair: the work of thirty artists set into the walls in groups by the kind of debt they carry, from student loans to mortgages and credit cards, with a website that gathered the stories of many more. Shown in a museum whose trustees include financiers, it asked who pays for an art career and who profits from it.","images":[{"n":"occupy-museums-debtfair-1","src":"assets/critique_additions/occupy-museums-debtfair-1.jpg","thumb":"assets/critique_additions/occupy-museums-debtfair-1_t.jpg","mid":"assets/critique_additions/occupy-museums-debtfair-1_m.jpg","w":2400,"h":1801,"artist":"Occupy Museums","project":"Debtfair","year":"2017","kind":"Installation view, Whitney Biennial, Whitney Museum of American Art, New York, 2017","credit":"Occupy Museums. Installation view. Debtfair, 2017. Thirty artworks and interactive website. Courtesy the artists. Whitney Museum of American Art, New York, N.Y. Photograph by Ronald Amstutz.","licence":"","source":"https://whitney.org/exhibitions/2017-biennial"}]},{"artist":"Andrea Fraser","project":"2016 in Museums, Money, and Politics","year":"2018","from":2018.2,"note":"","story":"For this work Fraser looked up the political donations made during the 2016 United States elections by the trustees of 128 American museums, and listed them, museum by museum, with the sums and the candidates and causes they went to. It was published as a book in 2018 and shown as prints and wall text. Set out in plain columns, the figures show how museum boards and political money overlap. The Whitney Museum, one of the museums listed, holds a set of the prints.","images":[{"n":"fraser-2016-in-museums-money-and-politics-1","src":"assets/critique_additions/fraser-2016-in-museums-money-and-politics-1.jpg","thumb":"assets/critique_additions/fraser-2016-in-museums-money-and-politics-1_t.jpg","mid":"assets/critique_additions/fraser-2016-in-museums-money-and-politics-1_m.jpg","w":1738,"h":2048,"artist":"Andrea Fraser","project":"2016 in Museums, Money, and Politics","year":"2018","kind":"Print, 2018. Collection of the Whitney Museum of American Art, New York","credit":"Purchase, with funds from the Print Purchase Fund. © Thea Westreich Wagner, Ethan Wagner, and Andrea Fraser.","licence":"","source":"https://whitney.org/collection/works/65567"}]},{"artist":"Decolonize This Place","project":"Protest at the Whitney Museum","year":"2019","from":2019.1,"note":"A protest over Warren Kanders, vice chair of the museum’s board","story":"In November 2018 tear gas canisters made by Safariland, a company owned by the Whitney's vice chair, Warren Kanders, were reported to have been fired at migrants at the United States border with Mexico. Museum staff wrote an open letter, and Decolonize This Place led nine weeks of protest in the spring of 2019, with banners and marches in the museum's lobby. In July 2019 several artists asked to withdraw their work from that year's Biennial, and Kanders resigned from the board days later.","images":[{"n":"decolonize-this-place-whitney-1","src":"assets/critique_additions/decolonize-this-place-whitney-1.jpg","thumb":"assets/critique_additions/decolonize-this-place-whitney-1_t.jpg","mid":"assets/critique_additions/decolonize-this-place-whitney-1_m.jpg","w":2400,"h":1800,"artist":"Decolonize This Place","project":"Protest at the Whitney Museum","year":"2019","kind":"Banners in the lobby of the Whitney Museum of American Art, New York, 5 April 2019","credit":"Perimeander / Wikimedia Commons. Photograph: Perimeander.","licence":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Decolonize_this_place_040519_whitney_museum_full_image.jpg"}]},{"artist":"Forensic Architecture","project":"Triple-Chaser","year":"2019","from":2019.2,"note":"","story":"Forensic Architecture, a research group based at Goldsmiths in London, made Triple-Chaser with Praxis Films for the 2019 Whitney Biennial. The film looks into the tear gas grenades made by Safariland, the company owned by the museum's vice chair Warren Kanders, and shows how the group trained software on synthetic images to find the canisters in footage from protests around the world. In July 2019 Forensic Architecture was among the artists who asked to withdraw from the Biennial; Kanders resigned days later.","images":[{"n":"forensic-architecture-triple-chaser-1","src":"assets/critique_additions/forensic-architecture-triple-chaser-1.jpg","thumb":"assets/critique_additions/forensic-architecture-triple-chaser-1_t.jpg","mid":"assets/critique_additions/forensic-architecture-triple-chaser-1_m.jpg","w":2400,"h":1782,"artist":"Forensic Architecture","project":"Triple-Chaser","year":"2019","kind":"Installation view, Whitney Biennial, Whitney Museum of American Art, New York, 2019","credit":"Installation view of the Whitney Biennial 2019 (Whitney Museum of American Art, New York, May 17-September 22, 2019). Forensic Architecture, Triple-Chaser, 2019. Photograph by Ron Amstutz.","licence":"","source":"https://whitney.org/exhibitions/2019-biennial"},{"n":"forensic-architecture-triple-chaser-2","src":"assets/critique_additions/forensic-architecture-triple-chaser-2.jpg","thumb":"assets/critique_additions/forensic-architecture-triple-chaser-2_t.jpg","mid":"assets/critique_additions/forensic-architecture-triple-chaser-2_m.jpg","w":2400,"h":1782,"artist":"Forensic Architecture","project":"Triple-Chaser","year":"2019","kind":"Installation view, Whitney Biennial, Whitney Museum of American Art, New York, 2019","credit":"Installation view of the Whitney Biennial 2019 (Whitney Museum of American Art, New York, May 17-September 22, 2019). Forensic Architecture, Triple-Chaser, 2019. Photograph by Ron Amstutz.","licence":"","source":"https://whitney.org/exhibitions/2019-biennial"}]},{"artist":"BP or not BP?","project":"Mass action at the British Museum","year":"2022","from":2022.3,"note":"A protest against the museum’s sponsor, the oil company BP","story":"BP or not BP? is a group of actors and activists who began in 2012 by staging uninvited theatre against the oil company's sponsorship of the Royal Shakespeare Company and the British Museum. On 23 April 2022 it filled the museum's Great Court for a day of protest, ending with a giant BP logo pulled apart and the crowd singing. The museum's contract with BP ran out in 2023, and in December that year it signed a new ten-year agreement with the company worth £50 million.","images":[{"n":"bp-or-not-bp-british-museum-2022-1","src":"assets/critique_additions/bp-or-not-bp-british-museum-2022-1.jpg","thumb":"assets/critique_additions/bp-or-not-bp-british-museum-2022-1_t.jpg","mid":"assets/critique_additions/bp-or-not-bp-british-museum-2022-1_m.jpg","w":2000,"h":1333,"artist":"BP or not BP?","project":"Mass action at the British Museum","year":"2022","kind":"The BP logo pulled apart in the Great Court of the British Museum, London, 23 April 2022","credit":"The giant logo is pulled apart. Photo by Ron Fassbender.","licence":"","source":"https://bp-or-not-bp.org/2022/04/24/mass-bp-action-at-british-museum-ends-with-creative-occupation-of-four-galleries/"},{"n":"bp-or-not-bp-british-museum-2022-2","src":"assets/critique_additions/bp-or-not-bp-british-museum-2022-2.jpg","thumb":"assets/critique_additions/bp-or-not-bp-british-museum-2022-2_t.jpg","mid":"assets/critique_additions/bp-or-not-bp-british-museum-2022-2_m.jpg","w":2400,"h":1600,"artist":"BP or not BP?","project":"Mass action at the British Museum","year":"2022","kind":"Performers lead the crowd in song, Great Court of the British Museum, London, 23 April 2022","credit":"Performers lead the crowd in song. Photo by Kristian Buus.","licence":"","source":"https://bp-or-not-bp.org/2022/04/24/mass-bp-action-at-british-museum-ends-with-creative-occupation-of-four-galleries/"}]},{"artist":"Guerrilla Girls","project":"Guerrilla Girls Review the Whitney","year":"1987","from":1987,"note":"","story":"In the spring of 1987, while the Whitney Biennial was on, the Guerrilla Girls put on an exhibition of their own at The Clocktower, a city-owned space in lower Manhattan run by the Institute for Art and Urban Resources. It set out, in posters and figures, how few women and artists of colour the Whitney had shown in its Biennials and its collection. The poster gives the dates and the place, under a Guerrilla Girl in her mask.","images":[{"n":"guerrilla-girls-review-the-whitney-1","src":"assets/critique_additions/guerrilla-girls-review-the-whitney-1.jpg","thumb":"assets/critique_additions/guerrilla-girls-review-the-whitney-1_t.jpg","mid":"assets/critique_additions/guerrilla-girls-review-the-whitney-1_m.jpg","w":1857,"h":2400,"artist":"Guerrilla Girls","project":"Guerrilla Girls Review the Whitney","year":"1987","kind":"Poster for the exhibition at The Clocktower, New York, 16 April to 17 May 1987. Tate collection","credit":"","licence":"","source":"https://www.tate.org.uk/art/artworks/guerrilla-girls-guerrilla-girls-review-the-whitney-p78798"}]},{"artist":"Guerrilla Girls","project":"It’s Even Worse in Europe","year":"1986","from":1986,"note":"","story":"In their first years the Guerrilla Girls pasted posters at night on the walls of SoHo, then New York's gallery district, naming the museums, galleries and critics that showed or wrote about few women. This 1986 poster is one sentence long and signed, as they all were, as a public service message from the conscience of the art world. Whatever the figures in New York, it says, the museums of Europe were worse. Tate, one of those museums, later acquired it.","images":[{"n":"guerrilla-girls-its-even-worse-in-europe-1","src":"assets/critique_additions/guerrilla-girls-its-even-worse-in-europe-1.jpg","thumb":"assets/critique_additions/guerrilla-girls-its-even-worse-in-europe-1_t.jpg","mid":"assets/critique_additions/guerrilla-girls-its-even-worse-in-europe-1_m.jpg","w":2400,"h":1857,"artist":"Guerrilla Girls","project":"It’s Even Worse in Europe","year":"1986","kind":"Poster, 1986. Tate collection","credit":"","licence":"","source":"https://www.tate.org.uk/art/artworks/guerrilla-girls-its-even-worse-in-europe-p78801"}]},{"artist":"Louise Lawler","project":"Etude pour La Lecture, 1923, This Drawing is for Sale, Paris","year":"1985","from":1985,"note":"","story":"Since the late 1970s Louise Lawler has photographed other artists' work where it ends up: in museums, private collections, auction rooms and storage. Her pictures show that a work's meaning changes with where it hangs and who owns it. Here a framed study by Fernand Léger stands propped on other pictures beside a leather seat, and the title, which names the drawing and says it is for sale in Paris, turns a masterpiece into stock.","images":[{"n":"lawler-etude-pour-la-lecture-1","src":"assets/critique_additions/lawler-etude-pour-la-lecture-1.jpg","thumb":"assets/critique_additions/lawler-etude-pour-la-lecture-1_t.jpg","mid":"assets/critique_additions/lawler-etude-pour-la-lecture-1_m.jpg","w":1536,"h":1006,"artist":"Louise Lawler","project":"Etude pour La Lecture, 1923, This Drawing is for Sale, Paris","year":"1985","kind":"Photograph, 1985. Tate collection","credit":"","licence":"","source":"https://www.tate.org.uk/art/artworks/lawler-etude-pour-la-lecture-1923-this-drawing-is-for-sale-paris-p79770"}]},{"artist":"Louise Lawler","project":"March 25, 1991","year":"1991","from":1991,"note":"","story":"Lawler took this picture of one of Roy Lichtenstein's large interior paintings, a living room drawn in his comic-book line, with two shipping crates standing in front of it on a bare floor. Titled only with the date, it catches the painting between places, packed or about to be, the way most art spends much of its life. It belongs to the work Lawler has made since the late 1970s on how art is handled, moved, stored and sold.","images":[{"n":"lawler-march-25-1991-1","src":"assets/critique_additions/lawler-march-25-1991-1.jpg","thumb":"assets/critique_additions/lawler-march-25-1991-1_t.jpg","mid":"assets/critique_additions/lawler-march-25-1991-1_m.jpg","w":1536,"h":1006,"artist":"Louise Lawler","project":"March 25, 1991","year":"1991","kind":"Photograph, 1991. Tate collection","credit":"","licence":"","source":"https://www.tate.org.uk/art/artworks/lawler-march-25-1991-p79772"}]},{"artist":"Louise Lawler","project":"Foreground","year":"1994","from":1994,"note":"","story":"A stainless steel rabbit by Jeff Koons, one of the most expensive sculptures of its time, stands on a plinth in a private apartment, while the photograph gives most of its space to the kitchen beside it: a fridge, cupboards and a counter. Lawler photographs art in the homes of collectors as she does in museums, and lets the setting speak. The title asks what is in the foreground, the art or the life of the people who own it.","images":[{"n":"lawler-foreground-1","src":"assets/critique_additions/lawler-foreground-1.jpg","thumb":"assets/critique_additions/lawler-foreground-1_t.jpg","mid":"assets/critique_additions/lawler-foreground-1_m.jpg","w":1006,"h":1536,"artist":"Louise Lawler","project":"Foreground","year":"1994","kind":"Photograph, 1994. Tate collection","credit":"","licence":"","source":"https://www.tate.org.uk/art/artworks/lawler-foreground-p79771"}]},{"artist":"Fred Wilson","project":"Grey Area","year":"1993","from":1993,"note":"","story":"A year after Mining the Museum, in which he rearranged the collection of the Maryland Historical Society to show the history of slavery it had kept out of sight, Fred Wilson made Grey Area. It sets five casts of the bust of Nefertiti side by side, painted in steps from white to black. The original was dug up at Amarna by a German expedition in 1912 and is in Berlin, which Egypt has asked to return. Wilson's row asks how museums have decided who the ancient Egyptians were, and whose history they are telling.","images":[{"n":"wilson-grey-area-1","src":"assets/critique_additions/wilson-grey-area-1.jpg","thumb":"assets/critique_additions/wilson-grey-area-1_t.jpg","mid":"assets/critique_additions/wilson-grey-area-1_m.jpg","w":1536,"h":629,"artist":"Fred Wilson","project":"Grey Area","year":"1993","kind":"Five painted plaster busts on wooden shelves, 1993. Tate collection","credit":"","licence":"","source":"https://www.tate.org.uk/art/artworks/wilson-grey-area-t13632"}]},{"artist":"Louise Lawler","project":"Adjusted","year":"2013–2014","from":2013,"note":"Her first large exhibition in Germany, 11 October 2013 to 26 January 2014","story":"Museum Ludwig gave Lawler her first large exhibition in Germany, curated by Philipp Kaiser. Rather than keeping to one suite of rooms, about 80 of her photographs were placed through the whole building, among the museum's own collection, so that her pictures of art in other museums, collections and auction rooms met the works on the walls beside them. She also made ten new tracings, outlines of her earlier photographs that look like pages of a colouring book, and two stretches, photographs printed on vinyl and pulled to fit the wall even where that distorts them.","images":[{"n":"lawler-adjusted-museum-ludwig-1","src":"assets/critique_additions/lawler-adjusted-museum-ludwig-1.jpg","thumb":"assets/critique_additions/lawler-adjusted-museum-ludwig-1_t.jpg","mid":"assets/critique_additions/lawler-adjusted-museum-ludwig-1_m.jpg","w":1920,"h":1280,"artist":"Louise Lawler","project":"Adjusted","year":"2013–2014","kind":"Installation view, Museum Ludwig, Cologne, 2013","credit":"Images courtesy of the artist; Metro Pictures, New York; and Museum Ludwig, Cologne. Photograph: Rheinisches Bildarchiv Köln / Sabrina Walz.","licence":"","source":"https://www.contemporaryartlibrary.org/project/louise-lawler-at-museum-ludwig-cologne-8134"},{"n":"lawler-adjusted-museum-ludwig-2","src":"assets/critique_additions/lawler-adjusted-museum-ludwig-2.jpg","thumb":"assets/critique_additions/lawler-adjusted-museum-ludwig-2_t.jpg","mid":"assets/critique_additions/lawler-adjusted-museum-ludwig-2_m.jpg","w":1920,"h":1280,"artist":"Louise Lawler","project":"Adjusted","year":"2013–2014","kind":"A photograph by Lawler of a museum room, shown at Museum Ludwig, Cologne, 2013","credit":"Images courtesy of the artist; Metro Pictures, New York; and Museum Ludwig, Cologne. Photograph: Rheinisches Bildarchiv Köln / Sabrina Walz.","licence":"","source":"https://www.contemporaryartlibrary.org/project/louise-lawler-at-museum-ludwig-cologne-8134"},{"n":"lawler-adjusted-museum-ludwig-3","src":"assets/critique_additions/lawler-adjusted-museum-ludwig-3.jpg","thumb":"assets/critique_additions/lawler-adjusted-museum-ludwig-3_t.jpg","mid":"assets/critique_additions/lawler-adjusted-museum-ludwig-3_m.jpg","w":1920,"h":1280,"artist":"Louise Lawler","project":"Adjusted","year":"2013–2014","kind":"One of Lawler’s tracings beside the museum’s Fernand Léger in the stairwell, Museum Ludwig, Cologne, 2013","credit":"Images courtesy of the artist; Metro Pictures, New York; and Museum Ludwig, Cologne. Photograph: Rheinisches Bildarchiv Köln / Sabrina Walz.","licence":"","source":"https://www.contemporaryartlibrary.org/project/louise-lawler-at-museum-ludwig-cologne-8134"}]}]};
